-- Extends the original single-assignee task table for MVP multi-employee assignment.
create table if not exists public.task_assignments (id uuid primary key default gen_random_uuid(), task_id uuid not null references public.tasks(id) on delete cascade, profile_id uuid not null references public.profiles(id) on delete cascade, status text not null default 'todo' check(status in ('todo','in_progress','completed')), updated_at timestamptz not null default now(), unique(task_id,profile_id));
alter table public.tasks add column if not exists created_by uuid references public.profiles(id) on delete set null, add column if not exists updated_at timestamptz not null default now();
alter table public.tasks drop constraint if exists tasks_status_check; alter table public.tasks add constraint tasks_status_check check(status in ('todo','in_progress','completed'));
alter table public.tasks drop constraint if exists tasks_priority_check; alter table public.tasks add constraint tasks_priority_check check(priority in ('low','medium','high'));
insert into public.task_assignments(task_id,profile_id,status) select id,assignee_id,status from public.tasks where assignee_id is not null on conflict(task_id,profile_id) do nothing;
create index if not exists task_assignments_profile_status_idx on public.task_assignments(profile_id,status); create index if not exists tasks_due_date_idx on public.tasks(due_date); create index if not exists task_comments_task_created_idx on public.task_comments(task_id,created_at);
drop trigger if exists tasks_touch_updated_at on public.tasks; create trigger tasks_touch_updated_at before update on public.tasks for each row execute function public.touch_updated_at();
drop trigger if exists task_assignments_touch_updated_at on public.task_assignments; create trigger task_assignments_touch_updated_at before update on public.task_assignments for each row execute function public.touch_updated_at();
create or replace function public.task_manager_can_manage(target uuid) returns boolean language sql stable security definer set search_path=public as $$ select public.is_management() or (public.current_role()='general_manager' and public.in_management_tree(target)) $$;
create or replace function public.enforce_task_assignment_update() returns trigger language plpgsql security definer set search_path=public as $$ begin if old.profile_id=auth.uid() and (new.task_id is distinct from old.task_id or new.profile_id is distinct from old.profile_id) then raise exception 'Employees cannot reassign tasks'; end if; return new; end $$;
drop trigger if exists enforce_task_assignment_update on public.task_assignments; create trigger enforce_task_assignment_update before update on public.task_assignments for each row execute function public.enforce_task_assignment_update();
alter table public.task_assignments enable row level security;
drop policy if exists "tasks visible to assignee or management" on public.tasks; create policy "tasks visible to assignee or management" on public.tasks for select to authenticated using(exists(select 1 from public.task_assignments a where a.task_id=id and (a.profile_id=auth.uid() or public.task_manager_can_manage(a.profile_id))));
drop policy if exists "tasks managers write" on public.tasks; create policy "tasks managers write" on public.tasks for all to authenticated using(public.is_management() or (public.current_role()='general_manager' and exists(select 1 from public.task_assignments a where a.task_id=id and public.in_management_tree(a.profile_id)))) with check(public.is_management() or created_by=auth.uid() or public.current_role()='general_manager');
create policy "task assignments read own or hierarchy" on public.task_assignments for select to authenticated using(profile_id=auth.uid() or public.task_manager_can_manage(profile_id));
create policy "task assignments manager writes" on public.task_assignments for insert to authenticated with check(public.task_manager_can_manage(profile_id));
create policy "task assignments employee status update" on public.task_assignments for update to authenticated using(profile_id=auth.uid()) with check(profile_id=auth.uid() and status in ('todo','in_progress','completed'));
create policy "task assignments manager update" on public.task_assignments for update to authenticated using(public.task_manager_can_manage(profile_id)) with check(public.task_manager_can_manage(profile_id));
drop policy if exists "comments visible to task audience" on public.task_comments; create policy "comments visible to task audience" on public.task_comments for select to authenticated using(exists(select 1 from public.task_assignments a where a.task_id=task_id and (a.profile_id=auth.uid() or public.task_manager_can_manage(a.profile_id))));
create policy "comments authored by task audience" on public.task_comments for insert to authenticated with check(author_id=auth.uid() and exists(select 1 from public.task_assignments a where a.task_id=task_id and (a.profile_id=auth.uid() or public.task_manager_can_manage(a.profile_id))));
